Here is an example of a game in p5.js with draggable sentence parts:

```
let sentenceParts = ["The", "cat", "sat", "on", "the", "mat."];
let draggedPart;
let partWidth = 60;
let partHeight = 30;
let gap = 10;

function setup() {
  createCanvas(600, 400);
  textAlign(CENTER, CENTER);
}

function draw() {
  background(255);
  displaySentenceParts();
  if (draggedPart) {
    dragPart();
  }
}

function mousePressed() {
  for (let i = 0; i < sentenceParts.length; i++) {
    let x = i * (partWidth + gap) + partWidth / 2;
    let y = height / 2;
    if (mouseX > x - partWidth / 2 && mouseX < x + partWidth / 2 && mouseY > y - partHeight / 2 && mouseY < y + partHeight / 2) {
      draggedPart = i;
      break;
    }
  }
}

function mouseDragged() {
  if (draggedPart !== null) {
    sentenceParts.splice(draggedPart, 1);
    draggedPart = null;
  }
}

function mouseReleased() {
  if (draggedPart !== null) {
    let x = mouseX;
    let y = height / 2;
    let index = Math.round((x - partWidth / 2) / (partWidth + gap));
    index = constrain(index, 0, sentenceParts.length);
    sentenceParts.splice(index, 0, draggedPart);
    draggedPart = null;
  }
}

function displaySentenceParts() {
  for (let i = 0; i < sentenceParts.length; i++) {
    let x = i * (partWidth + gap) + partWidth / 2;
    let y = height / 2;
    rect(x - partWidth / 2, y - partHeight / 2, partWidth, partHeight);
    text(sentenceParts[i], x, y);
  }
}

function dragPart() {
  let x = mouseX;
  let y = height / 2;
  let index = Math.round((x - partWidth / 2) / (partWidth + gap));
  index = constrain(index, 0, sentenceParts.length);
  sentenceParts.splice(draggedPart, 1);
  sentenceParts.splice(index, 0, draggedPart);
  draggedPart = null;
}
```

In this game, the sentence parts are displayed as rectangles with text in the center. The user can click and drag the parts to rearrange them into the correct order. The `displaySentenceParts()` function is called in the `draw()` loop to redraw the sentence parts every frame. The `mousePressed()` function checks if the user has clicked on a sentence part, and if so, sets the `draggedPart` variable to the index of that part. The `mouseDragged()` function moves the dragged part to the new position, and the `mouseReleased()` function updates the sentence parts array with the new order. The `dragPart()` function is called when the user is dragging a part, and it updates the position of the part based on the mouse position. The `constrain()` function is used to ensure that the index of the part is within the valid range.

